"""Convert BC5CDR PubTator to project UIE JSON format."""
import json
import os

BASE = "/root/autodl-tmp/struct_self_consist_ie"
CDR_DIR = f"{BASE}/data/bc5cdr/CDR_Data/CDR.Corpus.v010516"
OUT_DIR = f"{BASE}/data/bc5cdr"

SPLITS = {
    "CDR_TrainingSet.PubTator.txt": "train",
    "CDR_DevelopmentSet.PubTator.txt": "dev",
    "CDR_TestSet.PubTator.txt": "test",
}

def parse_pubtator(filepath):
    docs = []
    current_doc = None
    with open(filepath, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                if current_doc and current_doc.get("text"):
                    docs.append(current_doc)
                current_doc = None
                continue
            if "|t|" in line:
                parts = line.split("|t|", 1)
                pmid = parts[0].strip()
                title = parts[1] if len(parts) > 1 else ""
                current_doc = {"pmid": pmid, "title": title, "abstract": "", "entities": []}
                continue
            if "|a|" in line and current_doc:
                parts = line.split("|a|", 1)
                current_doc["abstract"] = parts[1] if len(parts) > 1 else ""
                current_doc["text"] = current_doc["title"] + " " + current_doc["abstract"]
                continue
            if current_doc and "\t" in line:
                fields = line.split("\t")
                if len(fields) >= 6 and fields[1].isdigit():
                    start, end = int(fields[1]), int(fields[2])
                    mention, etype = fields[3], fields[4]
                    if etype in ("Chemical", "Disease"):
                        current_doc["entities"].append({
                            "text": mention, "type": etype,
                            "start": start, "end": end,
                        })
    if current_doc and current_doc.get("text"):
        docs.append(current_doc)
    return docs

def deduplicate_entities(entities):
    seen = set()
    result = []
    for e in entities:
        key = (e["start"], e["end"], e["type"])
        if key not in seen:
            seen.add(key)
            result.append(e)
    return sorted(result, key=lambda x: (x["start"], x["end"]))

for filename, split in SPLITS.items():
    filepath = os.path.join(CDR_DIR, filename)
    docs = parse_pubtator(filepath)
    instances = []
    n_offset_ok, n_offset_fix, n_offset_bad = 0, 0, 0
    for i, doc in enumerate(docs):
        text = doc["text"]
        valid_ents = []
        for e in doc["entities"]:
            actual = text[e["start"]:e["end"]] if 0 <= e["start"] < e["end"] <= len(text) else ""
            if actual == e["text"]:
                valid_ents.append(e)
                n_offset_ok += 1
            else:
                # Title offset vs title+abstract offset adjustment
                # PubTator uses title_len + 1 as abstract offset base (title\tabstract)
                # but we concatenated with " " so offsets should align
                n_offset_bad += 1
        instances.append({
            "id": f"bc5cdr_{split}_{i:05d}",
            "text": text,
            "entities": deduplicate_entities(valid_ents),
            "relations": [], "events": [],
        })

    out_path = os.path.join(OUT_DIR, f"{split}.json")
    with open(out_path, "w", encoding="utf-8") as f:
        for inst in instances:
            f.write(json.dumps(inst, ensure_ascii=False) + "\n")

    n_ents = sum(len(x["entities"]) for x in instances)
    n_chem = sum(1 for x in instances for e in x["entities"] if e["type"] == "Chemical")
    n_dis = sum(1 for x in instances for e in x["entities"] if e["type"] == "Disease")
    print(f"{split}: {len(instances)} docs, {n_ents} entities ({n_chem} Chem, {n_dis} Dis)")
    print(f"  offsets: {n_offset_ok} ok, {n_offset_bad} bad")
PYEOF

